13	import { localDateFor } from "@/lib/outfits/local-date";
14	import { assertCanGenerate, noteGeneration, QuotaExceededError } from "@/lib/outfits/quota";
15	import { predictOccasion } from "@/lib/outfits/predict-occasion";
16	import { pinItem, styledLookName } from "@/lib/outfits/styled";
17	import { loadStyledLook, saveStyledLook } from "@/lib/outfits/styled-store";
18	import { resolveLocation } from "@/lib/weather/location";
19	import type { LookDraft, LookPiece, WeatherPayload } from "@/lib/generator/types";
20	
21	export type StyleResult =
22	  | { status: "ok"; outfitId: string }
23	  // Carries the seam's own reason. Styling is a Pro capability rather than a
24	  // daily allowance, so a message written here ("back tomorrow") would be
25	  // actively false — tomorrow gives a free user no stylings either.
26	  | { status: "limited"; message: string }
27	  | { status: "empty"; message: string }
28	  | { status: "error"; message: string };
29	
30	/**
31	 * "Style an outfit with this" (Fitcheck.dc.html:654).
32	 *
33	 * Pins the piece, runs the deterministic pipeline, spends ONE text call to name
34	 * and explain the result, then persists it keyed by (user, item, local day) so a
35	 * second tap the same day is a free read.
36	 *
37	 * This does not contradict Decision 5. That decision says never pay twice for a
38	 * question already answered — which is why the daily drop caches. "What goes
39	 * with this piece?" is a different question from "what should I wear today?",
40	 * so it gets its own answer, cached the same way.
41	 *
42	 * The alternative readings were measured and rejected; see the plan
43	 * `todo/2026-07-24-item-detail-rebuild.md`.
44	 */
45	export async function styleWithItem(itemId: string): Promise<StyleResult> {
46	  try {
47	    const supabase = await createClient();
48	    const {
49	      data: { user },
50	    } = await supabase.auth.getUser();
51	    if (!user) return { status: "error", message: "Not signed in" };
52	
53	    const { data: profile } = await supabase
54	      .from("profiles")
55	      .select(
56	        "archetype, formality_min, formality_max, occasions, location_lat, location_lon, location_label, location_source, location_timezone",
57	      )
58	      .eq("id", user.id)
59	      .single();
60	
61	    const { data: itemsRaw } = await supabase
62	      .from("items")
63	      .select("*")
64	      .eq("user_id", user.id)
65	      .eq("archived", false);
66	    const items = itemsRaw ?? [];
67	    const subject = items.find((i) => i.id === itemId);
68	    if (!subject) return { status: "error", message: "Piece not found" };
69	
70	    // Fragrance occupies no slot in a look, so there is nothing to build around.
71	    if (subject.category === "Fragrance") {
72	      return { status: "empty", message: "Fragrance finishes a look rather than forming one." };
73	    }
74	
75	    const now = new Date();
76	    // The date key comes from the PROFILE timezone, not the forecast's, so the
77	    // cache can be checked without a network call — the same zone `toggleWear`
78	    // and `predictDefaultOccasion` use.
79	    const today = localDateFor(now, profile?.location_timezone ?? "UTC");
80	
81	    // THE CACHE. Checked before the quota is touched and before any I/O beyond
82	    // this one indexed lookup — re-opening an answer you already have must never
83	    // cost anything.
84	    const cached = await loadStyledLook(user.id, itemId, today);
85	    if (cached) return { status: "ok", outfitId: cached };
86	
87	    // Checked before the forecast fetch below: a free user is turned away
88	    // without us paying for I/O they will never see. The occasion is not needed
89	    // here — a styled look is a flat capability (Pro #2), not a counted meter —
90	    // and it is resolved a few lines down, in time for the ledger.
91	    try {
92	      await assertCanGenerate(user.id, { kind: "styled", today });
93	    } catch (e) {
94	      if (e instanceof QuotaExceededError) return { status: "limited", message: e.message };
95	      throw e;
96	    }
97	
98	    const loc = resolveLocation({ profile });
99	    const f = await fetchForecast(loc.lat, loc.lon);
100	    const advice = laterAdvice(f.hourly);
101	    const weather: WeatherPayload = {
102	      tempC: f.tempC,
103	      feelsLikeC: f.feelsLikeC,
104	      condition: f.condition,
105	      cityLabel: loc.label,
106	      timezone: f.timezone,
107	      locationOrigin: loc.origin,
108	      laterSentence: advice.sentence,
109	      adviceClause: advice.adviceClause,
110	      laterLabel: "Later",
111	      hourly: f.hourly,
112	    };
113	
114	    // The occasion the app already believes you are dressing for today — the CTA
115	    // has no picker, and a look styled for the wrong context is worse than one
116	    // that simply agrees with the rest of the day.
117	    const occasion = predictOccasion(now, f.timezone, profile?.occasions ?? []);
118	
119	    /**
120	     * Pinning, done BEFORE candidate building rather than after.
121	     *
122	     * Dropping every rival in the subject's own category means any combo using
123	     * that category uses THIS piece. Filtering the built list instead would have
124	     * to survive the 200-combo CAP, and a piece that never made the cut would
125	     * silently produce "no looks" — the same class of bug as the coverage
126	     * defect fixed in PR #14.
127	     */
128	    const pool = items.filter((i) => i.category !== subject.category || i.id === itemId);
129	    const candItems: CandidateItem[] = pool.map((i) => ({
130	      id: i.id,
131	      colors: i.colors ?? [],
132	      category: i.category,
133	      formality: i.formality,
134	      seasons: i.seasons ?? [],
135	      material: i.material,
136	    }));
137	
138	    const args = {
139	      weather: { tempC: f.tempC, rain: f.hourly.some((h) => h.isNow && h.rain) },
140	      season: currentSeason(now),
141	      excludeItemIds: [],
142	      maxAccessories: 1,
143	    };
144	    const aesthetic = profile?.archetype ? [profile.archetype] : [];
145	
146	    // Try the day's own formality band first, then the full scale. A piece
147	    // dressier or more casual than today's context is still stylable — refusing
148	    // would be the "hard filter empties a required slot" trap again.
149	    let pinned: ReturnType<typeof rankTopN> = [];
150	    for (const band of [personalBand(occasion, profile), [1, 5] as [number, number]]) {
151	      const combos = buildCandidates(candItems, { ...args, band });
152	      const ranked = rankTopN(
153	        combos,
154	        { aesthetic, band, lean: [], recentlyShown: [], season: args.season },
155	        combos.length,
156	      );
157	      pinned = pinItem(ranked, itemId);
158	      if (pinned.length) break;
159	    }
160	
161	    if (!pinned.length) {
162	      return {
163	        status: "empty",
164	        message: "Not enough other pieces to build a look around this one yet.",
165	      };
166	    }
167	
168	    const byId = new Map(items.map((i) => [i.id, i]));
169	    const shortlist = pinned.slice(0, 20);
170	
171	    const { picks } = await rerank({
172	      want: 1,
173	      combos: shortlist.map((t) =>
174	        t.items.map((ci) => {
175	          const it = byId.get(ci.id)!;
176	          return { category: it.category, subcategory: it.subcategory, colors: it.colors ?? [] };
177	        }),
178	      ),
179	      aesthetic,
180	      occasion,
181	      weatherLabel: f.condition,
182	      tempC: f.tempC,
183	    });
184	
185	    const chosen = shortlist[picks[0]?.combo_index ?? 0] ?? shortlist[0];
186	    const dbItems = chosen.items.map((ci) => byId.get(ci.id)!);
187	    const paths = dbItems.map(displayPath);
188	    const signed = await signItemImages(paths);
189	    const slots = layoutForLook(dbItems.map((d) => ({ category: d.category })));
190	    const pieces: LookPiece[] = dbItems.map((d, idx) => ({
191	      itemId: d.id,
192	      category: d.category,
193	      subcategory: d.subcategory ?? null,
194	      brand: d.brand ?? null,
195	      name: d.name ?? null,
196	      colors: d.colors ?? [],
197	      cutoutUrl: signed.get(displayPath(d)) ?? "",
198	      slot: slots[idx],
199	    }));
200	
201	    const draft: LookDraft = {
202	      name: picks[0]?.name || styledLookName(subject),
203	      why: picks[0]?.why ?? "",
204	      pieces,
205	      anchorIndex: staggerOrder(slots)[0],
206	    };
207	
208	    const outfitId = await saveStyledLook(user.id, itemId, occasion, today, weather, draft);
209	    if (!outfitId) return { status: "error", message: "Couldn't save the look" };
210	
211	    // After the model answered AND the write landed. The occasion is known by
212	    // now, which is why recording is separate from the gate above.
213	    await noteGeneration(user.id, { kind: "styled", occasion, today });
214	
215	    return { status: "ok", outfitId };
216	  } catch (e) {
217	    console.error("[styleWithItem] failed:", e);
218	    return { status: "error", message: e instanceof Error ? e.message : "Couldn't style this" };
219	  }
220	}
